 $finance->saveAccountSettings($bank,2,true,'');$missing=$reports->interfaceRead('journal',$base);$check(count(array_filter($missing['rows'],static fn(array$r):bool=>str_contains($r['info'],'SKR-Kontonummer des Geldkontos fehlt')))===2,'consciously cleared current mapping retains the genuine missing-code diagnostic');
