  $db->beginTransaction();try{$db->exec("UPDATE clubs SET name='Own preceding conflicting bank report work' WHERE id='own-list-club'");$prior=ownOriginalDatabaseHash($db,$tables);$rejected=false;try{$reports->interfaceRead('journal',$base);}catch(DomainException$failure){$rejected=$failure->getCode()===503;}$check($rejected&&$db->inTransaction()&&ownOriginalDatabaseHash($db,$tables)===$prior,'catalogue conflict preserves genuine preceding caller transaction work');}finally{if($db->inTransaction())$db->rollBack();}
